pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner sends 1 wei to a non-existent contract (triggering fallback on the target, but here we test depositsCount on c)
        // Actually we need to call sendMoney which does call.value on _target, but the fallback is on C itself?
        // The fallback is on C, so to trigger it we must send ether to C directly. But sendMoney sends ether from C to _target, not to C.
        // Wait: The difference says: after sendMoney completes, depositsCount differs. That means the sendMoney call itself triggers C's fallback? No, sendMoney calls _target.call{value: _value}(""). This does not trigger C's fallback unless _target == address(c). 
        // But the difference statement says: P.depositsCount() != M.depositsCount() after a call to sendMoney(...). So we need a scenario where the fallback is triggered during sendMoney. How? If _target is C itself, then sending ether back to C triggers its fallback. Let's set _target = address(c) and _value = 1 wei.
        // Reference: C's fallback increments depositsCount regardless of caller. Mutant: fallback requires owner, so if caller is not owner, require fails and depositsCount doesn't increment.
        // But sendMoney is onlyOwner, so caller is owner. In mutant, fallback requires msg.sender == owner. Who is msg.sender when the fallback executes? It's the C contract itself (because sendMoney uses call.value from C), so msg.sender = address(c). address(c) != owner (owner is the deployer of C). So the require fails in mutant, reverting the call. So depositsCount stays unchanged. In reference, fallback succeeds, increments depositsCount.
        // So concrete scenario: owner calls sendMoney(address(c), 1). Reference: depositsCount becomes 1. Mutant: depositsCount remains 0.
        // Let's prepare: vm.deal(address(c), 1) to have ether to send? Actually sendMoney uses address(this).balance? No, sendMoney sends _value from the contract's balance. But C may have no ether initially. We'll need to deal some ether to C first.
        // Alternative: We can have owner send ether to C to trigger fallback directly? But the requirement says driven through sendMoney. So we need to ensure C has enough balance. Let's deal 1 ether to C first.

        vm.deal(address(c), 1 ether);

        // Owner calls sendMoney with _target = address(c) and _value = 1 wei
        vm.prank(c.owner());
        c.sendMoney(address(c), 1 wei);

        // In reference, depositsCount = 1. In mutant, depositsCount = 0.
        assertTrue(c.depositsCount() == 1);
    }
}

