pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is the test contract (address(this))
        // The contract C's fallback is payable, so sending ETH to it works
        // However, after sendMoney sends ETH to itself (c), withdrawAll will fail in reference because transfer to msg.sender (the test contract) reverts? No, test contract is address(this) which can receive ETH.
        // Need a scenario where transfer fails: send to a contract without payable fallback.
        // Deploy a receiver that has no fallback
        // Actually simpler: the test contract itself can receive ETH, so transfer works.
        // Instead, use the fact that the reference uses transfer which reverts on failure, but call does not.
        // Create a contract that reverts on receive.
        // But we can only interact via c. The sendMoney sends to _target; if _target reverts, transfer reverts, call does not.
        // We'll deploy a separate contract that reverts on receive.
        // However we cannot create new contracts in the test? We can, but the rule says only interact through c. We'll make _target=c, and then call withdrawAll with a value that will cause transfer to fail? No, transfer to owner always works.
        // I'll use a different approach: sendMoney to a contract that reverts. But then the bug won't be observable via c's public surface because sendMoney will succeed in M and revert in P, and we can check c's balance.
        // Let's deploy a simple reverting receiver:
        // But the test file must not define other contracts. So we use the existing contract c as the target and rely on the fact that after sendMoney, the owner calls withdrawAll which tries to transfer the entire balance to owner. In reference, if the owner is a contract without payable fallback, transfer fails. We can set owner to a contract that cannot receive ETH.
        // Actually the owner is initially msg.sender (the test contract). The test contract can receive ETH. So transfer works.
        // We need the owner to be a contract that cannot receive. We can change owner by... no, we cannot change owner.
        // Alternative: the bug difference is that in P, withdraw(uint) uses transfer which reverts on failure, in M it uses call which does not. So we need a scenario where the transfer fails.
        // The transfer fails only if the recipient is a contract that does not have a payable fallback or receive function. The owner is the test contract, which has a receive? In Foundry Test.sol, the Test contract does have a receive? By default it inherits from Test, which likely has a receive. Actually forge-std/Test.sol does not define a receive. So transfer to the test contract might revert because the test contract does not have a payable fallback.
        // Let's test that: we'll first fund the contract, then call withdrawAll; in P it will revert, in M it will succeed and balance becomes 0.
        //
        // Scenario:
        // 1. Fund c: vm.deal(address(c), 1 ether);
        // 2. Owner (test contract) calls c.withdrawAll()
        // In P: transfer(1 ether) to msg.sender (test contract) -> reverts because test contract has no payable fallback -> the call reverts.
        // In M: call{value: 1 ether}("") to msg.sender -> returns false but does not revert -> withdrawAll completes, c's balance becomes 0.
        //
        // Assert: after withdrawAll, address(c).balance = 0 in M but in P the call reverts, so the test catches it.
        vm.deal(address(c), 1 ether);
        // P: this call will revert; M: will succeed.
        // We need to catch the revert in the test:
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // In P, ok = false; in M, ok = true.
        uint256 bal = address(c).balance;
        assertTrue(ok == false || bal == 0); // This doesn't work because we need one assertion that holds for P and fails for M.
        // Better: For the reference, after the call, ok = false and bal = 1 ether.
        // For the bug, ok = true and bal = 0.
        // So we can assert that the balance is 1 ether (which holds for P, fails for M).
        // But we must ensure the call doesn't revert the whole test. So wrap in try/catch.
        try c.withdrawAll() {
            // succeeded: bug case
            assertTrue(address(c).balance == 0);
        } catch {
            // reverted: reference case
            assertTrue(address(c).balance == 1 ether);
        }
    }
}

