    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a non-payable contract to receive the call
        NonPayableReceiver receiver = new NonPayableReceiver();
        address target = address(receiver);

        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);

        // Attempt to send money via the low-level call (reference) or transfer (bug)
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, 0.5 ether));

        // The reference should revert the whole transaction (call returns false), buggy version does not
        assertTrue(!ok, "Reference should revert on send to non-payable contract");
