pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy an empty contract to serve as the target; it will receive ether but has no receive/fallback
        address target = address(new Empty());
        uint initialBalance = address(target).balance; // 0
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Have a non-owner call sendMoney; onlyOwner reverts on reference, succeeds on buggy
        address attacker = address(0x123);
        vm.deal(attacker, 1 ether); // not needed, but for safety
        vm.prank(attacker);
        // The call: if it reverts on reference, the catch sets ok=false; if it succeeds on buggy, ok=true
        bool ok;
        try c.sendMoney(target, 1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // After the call, the reference contract never sent ether, so target balance stays 0; buggy sent it, so balance becomes 1 ether
        assertTrue((ok == false && address(target).balance == 0) || (ok == true && address(target).balance == 1 ether));
    }
}

contract Empty {
    // No receive, no fallback — sendMoney's call will succeed but revert if the target had a receive/fallback? Actually .call{value} will succeed even if no receive? No, if no payable fallback/receive, the call reverts on the child side. Let's add a receive to make it simple.
    receive() external payable {}
}

